<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {get,post} from '../api'
import {withinWindow} from '../intelligence'
import EventDetail from '../components/EventDetail.vue'
import ReportPreview from '../components/ReportPreview.vue'
const route=useRoute(),router=useRouter(),all=ref<any[]>([]),companies=ref<any[]>([]),aliases=ref<any[]>([]),technologies=ref<string[]>([]),follows=ref<any[]>([]),loading=ref(false),failed=ref(false),page=ref(1),eventId=ref<number|null>(null),node=ref<any>(null),profile=ref<any>(null),expanded=ref(''),focused=ref<number|null>(null),limit=ref(24),digest=ref<any>(null)
const personal=computed(()=>route.path==='/following')
const f=computed(()=>({q:String(route.query.q||''),tech:String(route.query.tech||'').split(',').filter(Boolean),companies:String(route.query.companies||'').split(',').filter(Boolean),days:Number(route.query.days||0),level:String(route.query.level||''),view:String(route.query.view||(personal.value?'list':'matrix'))}))
function patch(value:any){page.value=1;router.replace({query:{...route.query,...value}})}
const rows=computed(()=>all.value.filter(e=>withinWindow(e,f.value.days)&&(!f.value.tech.length||e.directions.some((t:string)=>f.value.tech.includes(t)))&&(!f.value.companies.length||f.value.companies.includes(String(e.company_id)))&&(!f.value.level||e.evidence_levels.includes(f.value.level))&&(!personal.value||follows.value.some(x=>(x.target_type==='company'&&Number(x.target_key)===e.company_id)||(x.target_type==='technology'&&e.directions.includes(x.target_key))))))
const visibleCompanies=computed(()=>companies.value.filter(c=>(rows.value.some(e=>e.company_id===c.id)||!!f.value.q||f.value.companies.includes(String(c.id)))&&(!f.value.q||[c.name,...aliases.value.filter(a=>a.company_id===c.id).map(a=>a.alias)].some(s=>s.toLowerCase().includes(f.value.q.toLowerCase())))).sort((a,b)=>a.name.localeCompare(b.name)))
const visibleRows=computed(()=>rows.value.filter(e=>visibleCompanies.value.some(c=>c.id===e.company_id)))
const pagedCompanies=computed(()=>visibleCompanies.value.slice((page.value-1)*8,page.value*8))
const columns=computed(()=>f.value.tech.length?f.value.tech:technologies.value)
const cell=(id:number,t:string)=>visibleRows.value.filter(e=>e.company_id===id&&e.directions.includes(t))
async function companyNode(c:any){node.value={type:'company',id:c.id,name:c.name};profile.value=await get('/companies/'+c.id);focused.value=c.id}
function techNode(t:string){node.value={type:'technology',name:t};expanded.value=expanded.value===t?'':t;focused.value=null;profile.value=null}
const nodeRows=computed(()=>visibleRows.value.filter(e=>node.value?.type==='company'?e.company_id===node.value.id:node.value?.type==='project'?e.project_id===node.value.id:node.value?.type==='product'?e.title.includes(node.value.name):e.directions.includes(node.value?.name)).slice(0,10))
const graph=computed(()=>{const nodes:any[]=[];const edges:any[]=[];if(!expanded.value){technologies.value.filter(t=>!f.value.tech.length||f.value.tech.includes(t)).forEach((t,i)=>nodes.push({id:t,type:'tech',label:t,x:190+(i%3)*280,y:70+Math.floor(i/3)*110}));return {nodes,edges}}nodes.push({id:expanded.value,type:'tech',label:expanded.value,x:120,y:220});const comps=visibleCompanies.value.filter(c=>cell(c.id,expanded.value).length&&(!focused.value||c.id===focused.value)).slice(0,Math.min(8,limit.value-1));comps.forEach((c,i)=>{nodes.push({id:'c'+c.id,type:'company',company:c,label:c.name,x:430,y:50+i*55});edges.push({x1:120,y1:220,x2:430,y2:50+i*55})});if(focused.value){const entities=profile.value?.id===focused.value?[...(profile.value.products||[]).map((p:any)=>({id:'product'+p.id,type:'entity',kind:'product',entity:p,label:p.name})),...(profile.value.projects||[]).map((p:any)=>({id:'project'+p.id,type:'entity',kind:'project',entity:p,label:p.name}))].slice(0,4):[];const children=[...entities,...cell(focused.value,expanded.value).slice(0,8).map(e=>({id:'e'+e.id,type:'event',event:e,label:e.title}))];children.slice(0,limit.value-nodes.length).forEach((n,i)=>{nodes.push({...n,x:760,y:40+i*50});edges.push({x1:430,y1:50,x2:760,y2:40+i*50})})}return {nodes,edges}})
function graphClick(n:any){if(n.type==='tech')techNode(n.label);else if(n.type==='company')companyNode(n.company);else if(n.type==='entity')node.value={type:n.kind,id:n.entity.id,name:n.label};else eventId.value=n.event.id}
async function load(){loading.value=true;failed.value=false;try{[companies.value,technologies.value,aliases.value,follows.value]=await Promise.all(['/companies?limit=200','/workspace/technologies','/company-aliases','/workspace/follows'].map(get));const result:any[]=[];for(let offset=0;;offset+=500){const r=await get('/workspace/events?days=0&limit=500&offset='+offset);result.push(...r.items);if(result.length>=r.total)break}all.value=result}catch{failed.value=true}finally{loading.value=false}}
onMounted(load)
</script>
<template><div v-loading="loading"><div class="page-heading"><div><div class="eyebrow">EXPLORE / EVIDENCE FIRST</div><h1>{{personal?'我的关注情报流':'行业技术地图'}}</h1><p>筛选保存在地址栏，切换视图保留研究范围。</p></div><div><el-button @click="load">刷新</el-button><el-button v-if="personal" @click="post('/workspace/digest?days='+(f.days||7)+'&followed=true').then(r=>digest=r)">生成关注简报</el-button></div></div><el-alert v-if="failed" type="error" title="加载失败，请刷新"/>
<section class="panel"><div class="toolbar"><el-input :model-value="f.q" @update:model-value="patch({q:$event})" placeholder="搜索企业或别名，如智元 / AGIBOT" clearable style="width:260px"/><el-select :model-value="f.tech" @update:model-value="patch({tech:$event.join(',')})" multiple clearable collapse-tags placeholder="技术方向" style="width:240px"><el-option v-for="t in technologies" :key="t" :label="t" :value="t"/></el-select><el-select :model-value="f.companies" @update:model-value="patch({companies:$event.join(',')})" multiple clearable filterable collapse-tags placeholder="企业范围" style="width:220px"><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="String(c.id)"/></el-select><el-select :model-value="f.days" @update:model-value="patch({days:String($event)})" style="width:150px"><el-option label="全部资料" :value="0"/><el-option label="最近7天" :value="7"/><el-option label="最近30天" :value="30"/></el-select><el-select :model-value="f.level" @update:model-value="patch({level:$event})" clearable placeholder="证据等级" style="width:200px"><el-option v-for="l in ['company_claim','technical_artifact','customer_confirmation','independent_verification']" :key="l" :label="l" :value="l"/></el-select><el-button @click="router.replace({query:{}});expanded='';focused=null;page=1">重置</el-button></div><el-radio-group v-if="!personal" :model-value="f.view" @update:model-value="patch({view:$event})"><el-radio-button value="matrix">对比矩阵</el-radio-button><el-radio-button value="graph">局部关系图</el-radio-button><el-radio-button value="list">企业列表</el-radio-button></el-radio-group><p>{{visibleCompanies.length}} 家匹配企业 · {{visibleRows.length}} 个保守去重事件组。记录多不代表技术领先；没有证据不等于没有能力。</p></section>
<section v-if="f.view==='matrix'&&!personal" class="panel"><div class="matrix-wrap"><table class="matrix focused-map"><thead><tr><th>企业 / 技术</th><th v-for="t in columns" :key="t">{{t}}</th></tr></thead><tbody><tr v-for="c in pagedCompanies" :key="c.id"><th><el-button link @click="companyNode(c)">{{c.name}}</el-button></th><td v-for="t in columns" :key="t"><el-button v-if="cell(c.id,t).length" link @click="node={type:'company',id:c.id,name:c.name};profile=null">{{cell(c.id,t).some(e=>e.evidence_levels.some((l:string)=>['customer_confirmation','independent_verification','technical_artifact'].includes(l)))?'有公开证据':'待核验声明'}} · {{cell(c.id,t).length}}</el-button><span v-else class="muted">证据不足</span></td></tr></tbody></table></div><el-pagination v-model:current-page="page" :page-size="8" :total="visibleCompanies.length" layout="prev,pager,next,total"/></section>
<section v-else-if="f.view==='graph'&&!personal" class="panel"><div class="toolbar"><el-button @click="expanded='';focused=null">折叠至技术类别</el-button><el-button v-if="focused" @click="focused=null">返回企业邻居</el-button><span>可见节点上限</span><el-input-number v-model="limit" :min="10" :max="30"/></div><p>点击技术展开公司，再点击公司聚焦到事件；详情在侧栏查看。已显示 {{graph.nodes.length}} 个节点。</p><svg :viewBox="'0 0 980 '+Math.max(510,...graph.nodes.map(n=>n.y+50))" role="img" aria-label="局部行业技术关系图" style="width:100%;min-height:360px"><line v-for="(e,i) in graph.edges" :key="i" v-bind="e" stroke="#c7d9cc" stroke-width="2"/><g v-for="n in graph.nodes" :key="n.id" tabindex="0" role="button" :aria-label="n.label" @click="graphClick(n)" @keydown.enter="graphClick(n)" style="cursor:pointer"><rect :x="n.x-100" :y="n.y-19" width="200" height="38" rx="10" :fill="f.q&&n.label.toLowerCase().includes(f.q.toLowerCase())?'#fff0bd':n.type==='tech'?'#dceee1':'#f2f6f2'" stroke="#7fa68b"/><text :x="n.x" :y="n.y+4" text-anchor="middle" font-size="12" fill="#31573d">{{n.label.length>15?n.label.slice(0,15)+'…':n.label}}</text></g></svg></section>
<section v-else class="panel"><article v-for="c in pagedCompanies" :key="c.id" class="claim"><div class="section-heading"><el-button link @click="companyNode(c)">{{c.name}}</el-button><el-button @click="post('/workspace/follows',{target_type:'company',target_key:String(c.id)}).then(load)">关注企业</el-button></div><p>{{c.description}}</p><p>技术：{{[...new Set(visibleRows.filter(e=>e.company_id===c.id).flatMap(e=>e.directions))].join(' / ')}}</p><p>最近已知进展日期：{{visibleRows.filter(e=>e.company_id===c.id).map(e=>e.occurred_at||e.published_at||'').sort().at(-1)||'未知'}} · 事件组 {{visibleRows.filter(e=>e.company_id===c.id).length}}</p><el-button v-for="e in visibleRows.filter(e=>e.company_id===c.id).slice(0,3)" :key="e.id" link @click="eventId=e.id">{{e.title}}</el-button></article><el-pagination v-model:current-page="page" :page-size="8" :total="visibleCompanies.length" layout="prev,pager,next,total"/></section><el-empty v-if="!visibleCompanies.length" description="没有符合当前筛选的已保存记录。"/>
<el-drawer :model-value="!!node" @close="node=null" title="节点详情" size="min(650px,95vw)"><template v-if="node"><h2>{{node.name}}</h2><p>类型：{{node.type}}</p><p>{{profile?.description}}</p><router-link v-if="node.type==='company'" :to="'/companies/'+node.id">完整企业档案 →</router-link><p v-for="p in [...(profile?.products||[]),...(profile?.projects||[])]" :key="p.name">关联产品/项目：{{p.name}}</p><div v-for="e in nodeRows" :key="e.id" class="claim"><h3>{{e.title}}</h3><p>{{e.evidence_levels.join(' / ')}} · {{e.review_status}}</p><el-button link @click="eventId=e.id">来源、声明与不确定性</el-button></div></template></el-drawer><EventDetail :id="eventId" @close="eventId=null"/><el-dialog :model-value="!!digest" @close="digest=null" title="关注简报"><ReportPreview v-if="digest" :report="digest"/></el-dialog></div></template>
